a53ceeae77da7d1fb1093999f86890ae6d63b19a3d92712b417be2f10","lib/ediel/rulebook/utiltsRulebook.ts":"9e24ef3ffe369f63917faa0ee70754786550aa44c719b05baa4a5a5e3ac07227","lib/ediel/specRegistry.ts":"0ef212c09b6a6aaf3fc42c47e15b8e2cdb668984c3bb9f6ad2e925d4c9c59af8","lib/ediel/technicalExpectations.ts":"1c2b833f8e03890734d5ec25985007c4bdfd9d514945ca7d2ccfd93c99cf31ba","scripts/generate-ediel-native-technical-expectation-projection.cjs":"a180562d631677eaedb48bec2a331fce5d609dcf1bcc05a94ba7cc926ed1ac90"},"projection":{"constraints":{"version":1,"ruleId":"TM-CONTRL","offset":30,"unit":"minutes","anchor":"actual_accepted_smtp_observed_at","timerKind":"internal_sender_watch","remoteReceiptKnown":false},"ackMatrix":[{"family":"CONTRL","code":"*","technicalAck":"none","applicationAck":"none","businessResponses":[],"negativeApplicationResponse":"none","acknowledgeIncomingMessageWith":[]},{"family":"APERAK","code":"*","technicalAck":"CONTRL","applicationAck":"none","businessResponses":[],"negativeApplicationResponse":"none","acknowledgeIncomingMessageWith":["CONTRL"]},{"family":"UTILTS_ERR","code":"*","technicalAck":"CONTRL","applicationAck":"APERAK","businessResponses":[],"negativeApplicationResponse":"APERAK","acknowledgeIncomingMessageWith":["CONTRL","APERAK"]},{"family":"PRODAT","code":"Z01","technicalAck":"CONTRL","applicationAck":"none","businessResponses":["Z02"],"negativeApplicationResponse":"APERAK","acknowledgeIncomingMessageWith":["CONTRL"]},{"family":"PRODAT","code":"*","technicalAck":"CONTRL","applicationAck":"APERAK","businessResponses":[],"negativeApplicationResponse":"APERAK","acknowledgeIncomingMessageWith":["CONTRL","APERAK"]},{"family":"UTILTS","code":"*","technicalAck":"CONTRL","applicationAck":"transactional","businessResponses":[],"negativeApplicationResponse":"APERAK_OR_UTILTS_ERR","acknowledgeIncomingMessageWith":["CONTRL","APERAK","UTILTS_ERR"]}],"scopes":[{"family":"UTILTS","guideVersion":"25-A-3","guideRevision":"3","version":"25-A-3:r3","canonicalGuideRevision":"25-A-3","associationAssignedCode":"E5SE5A","documentName":"251001_Ediel_UTILTS-APERAK_User_Guide_Version_25-A-3"},{"family":"UTILTS","guideVersion":"25-A-4","guideRevision":"4","version":"25-A-4:r4","canonicalGuideRevision":"25-A-4","associationAssignedCode":"E5SE5A","documentName":"260331_Ediel_UTILTS-APERAK_User_Guide_Version_25-A-4"},{"family":"PRODAT","guideVersion":"26.A","guideRevision":"3","version":"26.A:r3","canonicalGuideRevision":"26-A","associationAssignedCode":"E2SE6A","documentName":"260630_Ediel_PRODAT_APERAK_Anvisning_version_26-A_16-B"},{"family":"CONTRL","guideVersion":"24-A-6","guideRevision":null,"version":"24-A-6","canonicalGuideRevision":"24-A-6","associationAssignedCode":null,"documentName":"260220_Ediel-anvisning-generella_tekniska_regler_version_24-A-6"}],"profiles":[{"family":"PRODAT","code":"Z01","profileKey":"prodat_z01_customer_identity_request"},{"family":"PRODAT","code":"Z02","profileKey":"prodat_z02_customer_identity_response"},{"family":"PRODAT","code":"Z03","profileKey":"prodat_z03_supplier_switch"},{"family":"PRODAT","code":"Z04","profileKey":"prodat_z04_supplier_switch_confirmation"},{"family":"PRODAT","code":"Z05","profileKey":"prodat_z05_old_supplier_confirmation"},{"family":"PRODAT","code":"Z06","profileKey":"prodat_z06_masterdata_grid_to_supplier"},{"family":"PRODAT","code":"Z08","profileKey":"prodat_z08_contract_end"},{"family":"PRODAT","code":"Z09","profileKey":"prodat_z09_masterdata_supplier_to_grid"},{"family":"PRODAT","code":"Z10","profileKey":"prodat_z10_meter_change"},{"family":"PRODAT","code":"Z13","profileKey":"prodat_z13_permission_request"},{"family":"PRODAT","code":"Z14","profileKey":"prodat_z14_permission_response"},{"family":"PRODAT","code":"Z15","profileKey":"prodat_z15_permission_ended"},{"family":"PRODAT","code":"Z18","profileKey":"prodat_z18_permission_end_request"},{"family":"UTILTS","code":"E66","profileKey":"utilts_e66"},{"family":"UTILTS","code":"E31","profileKey":"utilts_e31"},{"family":"UTILTS","code":"E30","profileKey":"utilts_e30"},{"family":"UTILTS","code":"E72","profileKey":"utilts_e72"},{"family":"UTILTS","code":"E73","profileKey":"utilts_e73"},{"family":"UTILTS","code":"E74","profileKey":"utilts_e74"},{"family":"UTILTS","code":"S01","profileKey":"utilts_s01"},{"family":"UTILTS","code":"S02","profileKey":"utilts_s02"},{"family":"UTILTS","code":"S03","profileKey":"utilts_s03"},{"family":"UTILTS","code":"S04","profileKey":"utilts_s04"},{"family":"UTILTS","code":"S05","profileKey":"utilts_s05"},{"family":"UTILTS","code":"S06","profileKey":"utilts_s06"},{"family":"UTILTS","code":"S07","profileKey":"utilts_s07"},{"family":"UTILTS_ERR","code":"ERR","profileKey":"utilts_err"},{"family":"APERAK","code":"APERAK","profileKey":null}],"logicalCodes":{"UTILTS_ERR":"ERR","APERAK":"APERAK","CONTRL":"CONTRL"}}}'::jsonb value) edition;
